<script setup lang="ts">
import {computed,reactive,ref,nextTick,watch,onBeforeUnmount} from 'vue';
import {useImagePreview} from '../app/imagePreview';
import {terminalSyncSummary} from '../domain/terminalSyncReport';
import {terminalJobNotice} from '../domain/terminalJobNotice';
import {logTarget} from '../app/logNavigation';
import type {ViewModel} from '../app/useWorkspace';
import {usePersonalTerminal} from '../app/usePersonalTerminal';
import {terminalMessageState} from '../app/terminalMessageState';
import {terminalMessageBubbles} from '../app/terminalMessageBubbles';
import {resetMajorCharacterImages} from '../app/localCharacterImages';
import {nicknameImage,saveNicknameImage} from '../app/localNicknameImages';
import NicknameImageSettings from './NicknameImageSettings.vue';
import CharacterAvatar from './CharacterAvatar.vue';
import GroupAvatar from './GroupAvatar.vue';
import CharacterImageEditor from './CharacterImageEditor.vue';
import {majorCharacter} from '../domain/characterImages';
import {contactCharacterId} from '../app/contactCharacter';
import AutoTextarea from './AutoTextarea.vue';
import {targetActors,groupOwner,groupMemberIds,groupNeedsManagement,groupManagementReady,kingParticipants,type KingRound} from '../domain/personalTerminal';
import {divinationPositions,suitName,suitGlyph,type TerminalDivination} from '../domain/divination';
import {messagePage,terminalMessageVisible,terminalAnchorActive} from '../domain/terminalLedger';
import TerminalActorAvatar from './TerminalActorAvatar.vue';
import TerminalIcon from './TerminalIcon.vue';
import PartyGameRoom from './PartyGameRoom.vue';
import GameChat from './GameChat.vue';
import DivinationCountdown from './DivinationCountdown.vue';
import {nextTerminalCourse} from '../domain/terminalSchedule';
const props=withDefaults(defineProps<{w:ViewModel;active?:boolean}>(),{active:true});defineEmits<{close:[];'drag-start':[event:PointerEvent];'drag-move':[event:PointerEvent];'drag-end':[]}>();
const u=reactive(usePersonalTerminal(props.w));
const avatarDisplay=useImagePreview(()=>u.t.avatar);
const syncVariant=computed(()=>{const turn=props.w.active?.turns.at(-1);return turn?.variants[turn.selected];});
const pendingMainFollowup=computed(()=>{const job=props.w.active&&terminalJobNotice(props.w.active);return job?[job]:[];});
const syncSummary=computed(()=>terminalSyncSummary(syncWarnings.value,syncVariant.value?.outcome?.terminal?.report));
const syncWarnings=computed(()=>props.w.active?.turns.at(-1)?.variants[props.w.active.turns.at(-1)!.selected]?.outcome?.stateUpdate?.codes?.filter(code=>code.startsWith('STATE_TERMINAL_'))||[]);
const syncNoticeVisible=ref(false);let syncNoticeTimer:ReturnType<typeof setTimeout>|undefined;
watch(()=>JSON.stringify([props.w.active?.id,props.w.active?.turns.at(-1)?.id,props.w.active?.turns.at(-1)?.selected,syncWarnings.value,props.w.storageStatus==='failed']),()=>{clearTimeout(syncNoticeTimer);syncNoticeVisible.value=props.w.storageStatus==='failed'||!!syncWarnings.value.length;if(syncNoticeVisible.value)syncNoticeTimer=setTimeout(()=>{syncNoticeVisible.value=false;},8000);},{immediate:true});
onBeforeUnmount(()=>clearTimeout(syncNoticeTimer));
function openSyncDetails(){const panel=props.w.storageStatus==='failed'?'cloud-backup':'format-errors';if(panel==='format-errors'&&props.w.active){const turn=props.w.active.turns.at(-1);if(turn)logTarget.value={sessionId:props.w.active.id,turnId:turn.id,variantId:syncVariant.value?.id||''};}props.w.panel=panel;window.dispatchEvent(new CustomEvent('academy:open',{detail:{panel}}));}
const homeAvatarFailed=ref(false);
watch(()=>u.t.avatar,()=>{homeAvatarFailed.value=false;});
const feed=ref<HTMLElement>(),avatarInput=ref<HTMLInputElement>();
const imageCharacter=ref(''),showImageCharacters=ref(false),majorResetMessage=ref('');
function resetMajorImages(){try{resetMajorCharacterImages(majorCharacters.value);majorResetMessage.value='主要角色头像已恢复默认，自定义昵称头像保留。';}catch{majorResetMessage.value='重置失败，请检查浏览器存储。';}}
const majorCharacters=computed(()=>(props.w.localService?.majorCharacters||props.w.localService?.characters||[]).filter(a=>majorCharacter(a.name)));
const titles:Record<string,string>={home:'个人终端',messages:'通讯',chat:'通讯',friends:'好友',add:'添加好友',profile:'好友资料','new-group':'发起群聊','invite-room':'邀请游戏好友','invite-group':'邀请好友','group-info':'群资料',courses:'课程表',course:'课程详情',apps:'应用',games:'游戏室','new-room':'创建房间',room:'国王游戏',king:'国王游戏',history:'游戏记录',divination:'每日占卜',account:'我的',legacy:'剧情群聊',party:'聚会游戏'};
const currentTitle=computed(()=>u.page==='chat'?u.conversation?.title||'通讯':titles[u.page]||'个人终端');
const filteredFriends=computed(()=>u.friends.filter(f=>(u.name(f.id)+f.note).includes(u.search)));
const searchedMessages=computed(()=>u.messages.filter(m=>!searchMessages.value||m.text.includes(chatSearch.value)));
const pagedMessages=computed(()=>messagePage(searchedMessages.value,u.historyPage));
const messageBubbles=computed(()=>terminalMessageBubbles(pagedMessages.value,!!u.conversation&&!u.conversation.group));
const emptyMessageState=computed(()=>!u.messages.length&&u.conversation&&props.w.active?terminalMessageState(props.w.active,u.conversation):undefined);
const mineWaiting=computed(()=>u.round?.phase==='respond'&&targetActors(u.round).includes('player')&&!u.round.replies.some(r=>r.id==='player'));
const npcWaiting=computed(()=>u.round?.phase==='respond'&&targetActors(u.round).some(id=>id!=='player'&&!u.round!.replies.some(r=>r.id===id)));
const chatSearch=ref(''),searchMessages=ref(false);
watch(chatSearch,()=>u.historyPage=0);
const conversations=computed(()=>u.visibleConversations.filter(c=>c.joined!==false&&c.title.includes(u.search)&&(u.conversationFilter==='all'||(u.conversationFilter==='group'?c.group:!c.group))));
const unconfirmedGroups=computed(()=>u.visibleConversations.filter(c=>groupNeedsManagement(c)));
const messageTime=(at:string)=>/^\d{1,2}:\d{2}$/.test(at)?at:/^\d{4}-/.test(at)?new Date(at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'';
const members=computed(()=>u.conversation?groupMemberIds(u.conversation):[]);
// Both of these run on every render, so they are computed once per room/conversation
// instead of being re-filtered inside the template for each row and each binding.
const roundsByRoom=computed(()=>{
 const session=props.w.active,rows=new Map<string,KingRound[]>();
 for(const r of u.t.rooms)rows.set(r.id,r.rounds.filter(x=>!x.archived&&(!x.anchor||!!session&&terminalAnchorActive(session,x.anchor))));
 return rows;
});
// Drunk/tolerance bars are shown for actual participants only: the player plus NPCs
 // whose invitation was accepted. Declined or waiting invitees are marked 未参加 and
 // never display a drunk state.
const roomParticipants=computed(()=>u.room?kingParticipants(u.room):[]);
const drunkStripVisible=computed(()=>roomParticipants.value.length>1||!!u.room&&!!u.room.endedAt);
const endedRoomsWithHistory=computed(()=>u.t.rooms.filter(r=>r.endedAt&&(roundsByRoom.value.get(r.id)?.length||0)));
const endedRoomsEmpty=computed(()=>u.t.rooms.filter(r=>r.endedAt&&!(roundsByRoom.value.get(r.id)?.length||0)));
function roundDialogueLines(round:KingRound){
 const lines:{id:string;text:string}[]=[{id:round.king,text:round.command||'尚未出令'},...round.replies.filter(x=>x.id!=='player').map(x=>({id:x.id,text:x.text}))];
 if(round.dialogue)lines.push(...round.dialogue.lines.map(x=>({...x})));
 for(const interaction of round.interactions||[]){lines.push({id:'player',text:interaction.text},...interaction.replies.filter(x=>x.id!=='player').map(x=>({id:x.id,text:x.text})));if(interaction.dialogue)lines.push(...interaction.dialogue.lines.map(x=>({...x})));}
 return lines;
}
const refusalFacts=(rows:{id:string;text:string;refused:boolean;penalty:string}[])=>rows.filter(r=>r.refused).map(r=>({id:r.id,text:r.penalty}));
function kingPenaltyFacts(round:KingRound){return [...refusalFacts(round.replies),...(round.interactions||[]).flatMap(interaction=>refusalFacts(interaction.replies))].filter(fact=>fact.text);}
const currentVisibleRounds=computed(()=>u.room?roundsByRoom.value.get(u.room.id)||[]:[]);
const groupAvatarUrl=ref(''),groupAvatarInput=ref<HTMLInputElement>(),groupAvatarPosition=ref({x:50,y:50});
async function groupAvatarChange(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(file){await u.uploadGroupAvatar(file);if(!u.error)groupAvatarPosition.value={x:50,y:50};}input.value='';}
function saveGroupAvatarUrl(){void u.setGroupAvatarUrl(groupAvatarUrl.value).then(()=>{if(!u.error)groupAvatarPosition.value={x:50,y:50};});}
function previewGroupAvatar(axis:'x'|'y',value:number){groupAvatarPosition.value={...groupAvatarPosition.value,[axis]:value};}
function saveGroupAvatarPosition(){void u.setGroupAvatarPosition({...groupAvatarPosition.value});}
function clearGroupAvatar(){void u.clearGroupAvatar().then(()=>{if(!u.error)groupAvatarPosition.value={x:50,y:50};});}
const friendAvatarUrl=ref(''),friendAvatarMessage=ref('');
const friendImageId=computed(()=>contactCharacterId(props.w.localService?.majorCharacters||[],u.friendId,u.name(u.friendId)));
const announcementOpen=ref(false);
watch(()=>u.conversationId,()=>announcementOpen.value=false);
watch(()=>u.friendId,()=>{friendAvatarUrl.value=u.friendId?nicknameImage(u.name(u.friendId)):'';friendAvatarMessage.value='';},{immediate:true});
function saveFriendAvatar(){try{saveNicknameImage(u.name(u.friendId),friendAvatarUrl.value);friendAvatarMessage.value=friendAvatarUrl.value.trim()?'自定义头像已保存到本机。':'已恢复该角色的默认头像。';}catch(e){friendAvatarMessage.value=e instanceof Error?e.message:'头像保存失败。';}}
const groupRole=(id:string)=>u.conversation&&groupOwner(u.conversation)===id?'群主':u.conversation?.adminIds?.includes(id)?'管理员':'成员';
function member(id:string){if(id==='player'){u.go('account');return;}if(u.friends.some(f=>f.id===id))profile(id);else{u.go('add');}}
const shownCourses=computed(()=>u.courses.filter(c=>u.week||!u.storyClock.day||c.day===u.storyClock.day).sort((a,b)=>a.day-b.day||a.time.localeCompare(b.time)));
const nextCourse=computed(()=>nextTerminalCourse(u.courses,u.storyClock));
const nav=computed(()=>['messages','chat','group-info','new-group','invite-group','legacy'].includes(u.page)?'messages':['friends','add','profile'].includes(u.page)?'friends':u.page==='home'?'home':['account','apps'].includes(u.page)?'account':'');
function profile(id:string){u.friendId=id;u.note=u.t.friends.find(f=>f.id===id)?.note||'';u.go('profile');}
function startRoom(){u.title='';u.picked=[];u.inviteNote='';u.go('new-room');}
const lockedGames=['狼人杀','日麻','斗地主'];
// runtime binding: static src would be rewritten by the SFC asset pipeline and break SSR tests
const divinationCatImage='/assets/divination-cat.png';
const divTab=ref<'mine'|'peek'>('mine'),partyKind=ref<'eleven'|'truth'|'liar'>('eleven');
const partyVisited=ref(false),partyView=ref<{handleBack:()=>boolean;enter:(kind:'eleven'|'truth'|'liar')=>void}>();
function openParty(kind:'eleven'|'truth'|'liar'){partyKind.value=kind;partyVisited.value=true;u.go('party');void nextTick(()=>partyView.value?.enter(kind));}
const reversedLabel=(reversed:boolean)=>reversed?'逆位':'正位';
const readingBlocks=(record:TerminalDivination|undefined|null):[string,string|undefined][]=>record&&record.reading.status==='ready'?[['今日基调',record.reading.overall],['感情',record.reading.love],['事业／学业',record.reading.career],['注意事项',record.reading.caution]]:[];
function groupInfo(){u.title=u.conversation?.title||'';u.note=u.conversation?.announcement||'';groupAvatarUrl.value=u.conversation?.avatar||'';groupAvatarPosition.value={...u.conversation?.avatarPosition||{x:50,y:50}};u.go('group-info');}
function back(){if(u.page==='party'&&partyView.value?.handleBack())return;const destination:Record<string,string>={chat:'messages',profile:'friends',add:'friends','new-group':'messages','group-info':'chat','invite-room':'room','invite-group':'group-info',course:'courses',courses:'home',games:'home','new-room':'games',room:'games',king:'room',history:'king',divination:'games',account:'home',legacy:'messages',party:'games'};u.go(destination[u.page]||'home');}
async function avatarChange(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(file)await u.uploadAvatar(file);input.value='';}
watch(()=>[u.conversation?.messages.length,u.page],async()=>{await nextTick();if(feed.value)feed.value.scrollTop=feed.value.scrollHeight;});
const weekNames=['周一','周二','周三','周四','周五','周六','周日'];
</script>
<template>
<section class="pt" aria-label="个人终端"><div v-if="u.inviteTarget" class="pt-image-dialog" role="dialog" aria-modal="true" aria-label="游戏邀请留言"><h2>邀请{{u.inviteTarget==='*'?'未加入的好友':u.name(u.inviteTarget)}}</h2><label>邀请留言（可选）<textarea v-model="u.inviteNote" maxlength="2000" rows="4" placeholder="留空发送默认邀请"/></label><p v-if="u.error" role="alert">{{u.error}}</p><div class="pt-actions"><button type="button" :disabled="u.working" @click="u.sendInvite">发送邀请</button><button type="button" :disabled="u.working" @click="u.inviteTarget=''">取消</button></div></div><div v-if="imageCharacter" class="pt-image-dialog" role="dialog" aria-modal="true" aria-label="编辑角色头像" @keydown.esc="imageCharacter=''"><button type="button" class="pt-image-close" aria-label="关闭头像编辑" autofocus @click="imageCharacter=''">关闭 ×</button><CharacterImageEditor :key="imageCharacter" :w="w" :id="imageCharacter"/></div>
 <header class="pt-header" title="拖动顶栏移动终端" @pointerdown="$emit('drag-start',$event)" @pointermove="$emit('drag-move',$event)" @pointerup="$emit('drag-end')" @pointercancel="$emit('drag-end')" @lostpointercapture="$emit('drag-end')"><button type="button" :aria-label="u.page==='home'?'返回桌面':'返回上一页'" @click="back">‹</button><div><strong>{{currentTitle}}</strong><small>STELLAR OS</small></div><span>{{u.clock.time}}</span><button type="button" aria-label="关闭个人终端" @click="$emit('close')">×</button></header>
 <div v-if="u.working" class="pt-progress" role="status">正在等待角色回应… <button type="button" disabled>请稍候</button></div>
 <div v-if="u.error" class="pt-error" role="alert">{{u.error}}<button type="button" aria-label="收起终端提示" @click="u.error=''">×</button></div>
 <div v-if="syncNoticeVisible" class="pt-sync-warning" role="status"><span>第 {{w.active?.turns.length}} 轮 · {{w.storageStatus==='failed'?'终端数据尚未保存，请先下载备份，保留当前页面。':syncSummary}}</span><button type="button" @click="openSyncDetails();$emit('close')">{{w.storageStatus==='failed'?'下载备份':'查看运行日志'}}</button></div>
 <main class="pt-screen" :class="{'pt-home-screen':u.page==='home'}" :aria-busy="u.working">
  <template v-if="u.page==='home'">
   <div class="pt-clock"><small>PERSONAL TERMINAL</small><b>{{u.clock.time}}</b><span>{{u.clock.label}}</span><small v-if="u.storyClock.location">{{u.storyClock.location}}</small><button class="pt-own" type="button" aria-label="设置终端头像" @click="u.go('account')"><img v-if="u.t.avatar&&!homeAvatarFailed" :src="avatarDisplay" :style="u.avatarStyle" alt="我的终端头像" @error="homeAvatarFailed=true"><TerminalIcon v-else name="user"/></button></div>
   <button class="pt-card pt-notification" type="button" @click="u.go('messages')"><TerminalIcon name="chat"/><div><strong>未读消息 <em v-if="u.unread">{{u.unread}}</em></strong><p>{{u.visibleConversations.find(c=>c.unread)?.messages.at(-1)?.text||'暂时没有新消息'}}</p></div><span>›</span></button>
   <div class="pt-launch-grid"><button v-for="app in [{id:'messages',icon:'chat',name:'通讯',hint:'私聊与群聊'},{id:'friends',icon:'friends',name:'好友',hint:'好友列表 · 添加好友'},{id:'courses',icon:'calendar',name:'课程表',hint:'课程 · 授课安排'},{id:'games',icon:'crown',name:'游戏室',hint:'国王游戏'}]" :key="app.id" type="button" class="pt-app" :class="{gold:app.id==='games'}" @click="u.go(app.id)"><TerminalIcon :name="app.icon"/><strong>{{app.name}}<em v-if="app.id==='friends'&&u.incoming.length"> {{u.incoming.length}}</em></strong><small>{{app.hint}}</small></button></div>
   <button class="pt-card pt-next" type="button" @click="u.go('courses')"><TerminalIcon name="calendar"/><div><small>下一节课</small><strong>{{nextCourse?.title||'暂无已知课程'}}</strong><p>{{nextCourse?`${nextCourse.time} · ${nextCourse.place}`:'打开课程表，读取剧情中的安排'}}</p></div><span>›</span></button>
  </template>
  <template v-else-if="u.page==='messages'">
   <article v-for="job in pendingMainFollowup" :key="job.id" class="pt-card" role="status"><strong>正文完成，终端部分未完成</strong><p>{{job.error||'正在补齐本轮终端消息…'}}</p><button v-if="job.status!=='running'&&w.terminalEnabled" type="button" :disabled="w.busy||w.terminalBusy||u.working" @click="w.retryTerminalJob(job.id)">重试补齐终端</button></article>
   <article v-for="i in u.incomingGroups" :key="i.id" class="pt-card pt-friend-request"><strong>{{u.name(i.by)}}邀请你加入{{u.t.conversations.find(c=>c.id===i.groupId)?.title||'群聊'}}</strong><p>{{i.reason}}</p><div class="pt-actions"><button type="button" :disabled="u.working||w.busy" @click="u.answerGroupInvitation(i.id,true)">同意加入</button><button type="button" :disabled="u.working||w.busy" @click="u.answerGroupInvitation(i.id,false)">拒绝</button></div></article>
   <article v-for="i in u.pendingGroupWelcomes" :key="'welcome:'+i.id" class="pt-card"><strong>{{u.t.conversations.find(c=>c.id===i.groupId)?.title}} · 已加入，欢迎消息待补</strong><p>{{i.welcome?.error||'成员资格已保存，可单独补齐欢迎消息。'}}</p><button type="button" :disabled="u.working||w.busy" @click="u.retryGroupWelcome(i.id)">补齐欢迎消息</button></article>
   <div class="pt-toolbar"><h2>通讯</h2><button v-if="unconfirmedGroups.length" type="button" :disabled="u.working" @click="u.completeGroupManagement">补全未确认群管理（{{unconfirmedGroups.length}}）</button><div class="pt-plus-wrap"><button type="button" aria-label="通讯操作" :aria-expanded="u.plusOpen" @click="u.plusOpen=!u.plusOpen">＋</button><div v-if="u.plusOpen" class="pt-plus-menu"><button type="button" @click="u.go('add')">添加好友</button><button type="button" @click="u.picked=[];u.title='';u.go('new-group')">发起群聊</button></div></div></div>
   <input v-model="u.search" aria-label="搜索会话" placeholder="搜索会话"><div class="pt-tabs"><button v-for="filter in [{id:'all',name:'全部'},{id:'private',name:'私聊'},{id:'group',name:'群聊'}] as const" :key="filter.id" type="button" :class="{active:u.conversationFilter===filter.id}" @click="u.conversationFilter=filter.id">{{filter.name}}</button></div>
   <p v-if="!u.visibleConversations.length" class="pt-empty">还没有会话<br>从好友资料发起私聊，或创建群聊。</p>
   <button v-for="c in conversations" :key="c.id" class="pt-row" type="button" @click="u.openConversation(c.id)"><span class="pt-avatar"><GroupAvatar v-if="c.group" :conversation="c"/><CharacterAvatar v-else :w="w" :id="c.members[0]||''"/></span><div><strong>{{c.title}}</strong><small>{{c.lastMessage?.text||'暂无消息'}}</small><small v-if="c.origin==='story'">剧情群聊</small></div><time>{{messageTime(c.lastMessage?.at||'')}}</time><em v-if="c.unread">{{c.unread}}</em><span>›</span></button>
  </template>
  <template v-else-if="u.page==='chat'&&u.conversation">
   <div class="pt-chat-identity"><span class="pt-avatar"><GroupAvatar v-if="u.conversation.group" :conversation="u.conversation"/><CharacterAvatar v-else :w="w" :id="u.conversation.members[0]||''"/></span><div><strong>{{u.conversation.title}}</strong><small>{{u.conversation.group?`${members.length}位成员 · ${groupRole('player')}`:'私聊'}}</small></div><button type="button" @click="u.conversation.group?groupInfo():profile(u.conversation.members[0])">{{u.conversation.group?'群资料':'好友资料'}} ›</button></div>
   <input v-if="searchMessages" v-model="chatSearch" aria-label="搜索聊天记录" placeholder="搜索本群聊天记录">
   <button v-if="u.conversation.announcement" type="button" class="pt-announcement pt-announcement-toggle" :aria-expanded="announcementOpen" @click="announcementOpen=!announcementOpen"><span :class="{collapsed:!announcementOpen}">群公告：{{u.conversation.announcement}}</span><small>{{announcementOpen?'收起':'展开'}}</small></button>
   <div class="pt-pagination" v-if="searchedMessages.length>20"><button type="button" :disabled="(u.historyPage+1)*20>=searchedMessages.length" @click="u.historyPage++">更早记录</button><small>第 {{u.historyPage+1}} 页 · 共 {{searchedMessages.length}} 条</small><button type="button" :disabled="u.historyPage===0" @click="u.historyPage--">较新记录</button></div>
   <div ref="feed" class="pt-chat-feed" role="log" aria-label="终端聊天消息"><div v-if="emptyMessageState" class="pt-empty"><p>{{emptyMessageState.stored?'已有记录暂未显示。':'从一句问候开始。'}}</p><details class="pt-message-state"><summary>查看消息状态</summary><p>已保存 {{emptyMessageState.stored}} 条 · 重新核对可显示 {{emptyMessageState.visible}} 条</p><p>归档 {{emptyMessageState.archived}} 条 · 剧情绑定变化 {{emptyMessageState.anchorChanged}} 条 · 行动来源变化 {{emptyMessageState.sourceChanged}} 条</p></details></div><article v-for="m in messageBubbles" :key="m.bubbleKey" class="pt-message" :class="{mine:m.sender==='player'}"><span class="pt-avatar"><img v-if="m.sender==='player'&&u.t.avatar" :src="avatarDisplay" :style="u.avatarStyle" alt="我的头像"><CharacterAvatar v-else :w="w" :id="m.sender" :nickname="m.displayName||u.name(m.sender)"/></span><div><small>{{m.displayName||u.name(m.sender)}}</small><p>{{m.text}}</p><time>{{m.source?'剧情记录':messageTime(m.at)}}</time></div></article></div>
   <button v-if="u.messages.at(-1)?.sender==='player'" type="button" class="pt-link" :disabled="u.working" @click="u.sendChat(true)">重试角色回复</button>
   <form class="pt-composer" @submit.prevent="u.sendChat()"><AutoTextarea v-model="u.draft" aria-label="终端消息" placeholder="输入消息…" maxlength="2000" rows="1"/><button type="submit" class="pt-primary" :disabled="u.working||!u.draft.trim()">发送</button></form><small class="pt-composer-hint">发送将调用终端 API</small>
  </template>
  <template v-else-if="u.page==='friends'">
