   <h3 v-if="u.activeFriends.some(f=>f.status!=='accepted'&&!(f.direction==='incoming'&&f.status==='pending'))">申请记录</h3><article v-for="f in u.activeFriends.filter(f=>f.status!=='accepted'&&!(f.direction==='incoming'&&f.status==='pending'))" :key="f.id" class="pt-card"><strong>{{u.name(f.id)}} · {{f.status==='pending'?'等待回应':'未接受'}}</strong><p>{{f.reply}}</p><button v-if="f.direction!=='incoming'&&f.code" type="button" :disabled="u.working" @click="u.friendApply(f.id)">{{f.status==='pending'?'重新获取回应':'再次申请'}}</button></article>
  </template>
  <template v-else-if="u.page==='add'">
