  <template v-else-if="u.page==='profile'">
   <div class="pt-profile"><h2>{{u.name(u.friendId)}}</h2><span class="pt-avatar large"><CharacterAvatar :w="w" :id="u.friendId"/></span><span>已是好友</span></div><p>{{u.actors.find(a=>a.id===u.friendId)?.identity||'暂无已知身份资料'}}</p><p>{{u.actors.find(a=>a.id===u.friendId)?.relationship||'关系以当前剧情为准'}}</p><p class="pt-card" v-if="u.t.friends.find(f=>f.id===u.friendId)?.reply">{{u.t.friends.find(f=>f.id===u.friendId)?.reply}}</p><div v-if="u.friendId.startsWith('contact-')||!majorCharacter(u.actors.find(a=>a.id===u.friendId)?.name||'')" class="pt-card"><label>自定义头像链接<input v-model="friendAvatarUrl" aria-label="自定义头像链接" placeholder="https://…，留空恢复默认头像"></label><button type="button" :disabled="u.working" @click="saveFriendAvatar">保存自定义头像</button><small role="status">{{friendAvatarMessage}}</small></div><CharacterImageEditor v-if="friendImageId" :key="friendImageId" :w="w" :id="friendImageId"/><small v-else class="pt-muted">使用上方图片链接，为这位联系人设置头像。</small><label>备注（仅自己可见）<input v-model="u.note" maxlength="1000"></label><button type="button" :disabled="u.working" @click="u.updateNote">保存备注</button><div class="pt-actions"><button type="button" class="pt-primary" :disabled="u.working" @click="u.openChat(u.friendId)">发送消息</button><button type="button" @click="u.picked=[u.friendId];u.title='';u.go('new-group')">邀请群聊</button><button type="button" class="pt-gold" @click="u.picked=[u.friendId];u.title='';u.go('new-room')">邀请游戏</button></div><button class="pt-link" type="button" :disabled="u.working" @click="u.removeFriend">移除好友（保留聊天记录）</button>
  </template>
  <template v-else-if="['room','king','invite-room'].includes(u.page)&&u.room?.endedAt"><h2>{{u.room.name}}</h2><p v-if="currentVisibleRounds.length">游戏已结束，只能回看记录。</p><p v-else>未开始，未生成回看。</p><button v-if="currentVisibleRounds.length" type="button" @click="u.go('history')">游戏记录</button><button v-if="u.endSaveFailed===u.room.id" type="button" @click="u.askEnd">重试保存结束状态</button><button v-else type="button" @click="u.go('games')">返回游戏室</button></template>
  <template v-else-if="['new-group','invite-group','new-room','invite-room'].includes(u.page)">
