   <h3 v-if="u.incoming.length">好友申请 · {{u.incoming.length}}</h3><article v-for="f in u.incoming" :key="'request:'+f.id" class="pt-card pt-friend-request"><span class="pt-avatar"><TerminalIcon name="user"/></span><div><strong>{{u.name(f.id)}}</strong><p>{{f.requestReason||f.reply}}</p><small>{{messageTime(f.at||'')}}</small><div class="pt-actions"><button type="button" class="pt-gold" :disabled="u.working" @click="u.answerRequest(f.id,true)">接受</button><button type="button" :disabled="u.working" @click="u.answerRequest(f.id,false)">拒绝</button></div></div></article>
