  <template v-else-if="u.page==='courses'">
   <div class="pt-toolbar"><h2>{{/教官|教师|教授/.test(w.active?.persona.identity||'')?'授课安排':'我的课程'}}</h2><button type="button" :disabled="u.working" @click="u.schedule">更新安排</button></div><div class="pt-tabs"><button type="button" :class="{active:!u.week}" @click="u.week=false">今日</button><button type="button" :class="{active:u.week}" @click="u.week=true">本周</button></div><p>{{u.storyClock.label}}</p><small v-if="!u.week&&!u.storyClock.day">剧情未明确星期，暂列出已知安排。</small><div v-if="u.week&&u.t.courses.length" class="pt-week-wrap"><div class="pt-week-grid"><section v-for="(day,index) in weekNames" :key="day"><strong>{{day}}</strong><button v-for="c in u.t.courses.filter(c=>c.day===index+1)" :key="c.id" type="button" @click="u.courseId=c.id;u.go('course')"><small>{{c.time}}</small>{{c.title}}</button></section></div></div><p v-if="!shownCourses.length" class="pt-empty">暂无明确的课程安排<br>没有明确安排时，可根据你的身份生成。</p><button v-for="c in shownCourses" :key="c.id" type="button" class="pt-course pt-card" @click="u.courseId=c.id;u.go('course')"><span>{{weekNames[c.day-1]}}<b>{{c.time}}</b></span><div><strong>{{c.title}}</strong><p>{{c.place||'地点待明确'}}</p></div><span>›</span></button><small v-if="u.t.scheduleDate">上次读取：{{u.t.scheduleDate}}</small>
  </template>
  <template v-else-if="u.page==='course'&&u.course"><small>{{weekNames[u.course.day-1]}}</small><h2>{{u.course.title}}</h2><h3>{{u.course.time}}—{{u.course.end}}</h3><article class="pt-card"><p>授课角色：{{u.course.teacherId?u.name(u.course.teacherId):'待明确'}}</p><p>地点：{{u.course.place||'待明确'}}</p><p>课前准备：{{u.course.preparation||'暂无已知要求'}}</p></article><button v-if="u.course.teacherId" type="button" class="pt-primary" :disabled="u.working" @click="u.friends.some(f=>f.id===u.course!.teacherId)?u.openChat(u.course.teacherId):u.go('add')">{{u.friends.some(f=>f.id===u.course!.teacherId)?'联系授课角色':'添加授课角色好友'}}</button><button type="button" @click="u.go('messages')">查看已有群聊</button></template>
  <template v-else-if="u.page==='games'"><div class="pt-game-hero"><TerminalIcon name="crown"/><h2>游戏室</h2><p>和好友一起玩。</p></div><h3>游戏列表</h3><button type="button" class="pt-row" @click="startRoom"><TerminalIcon name="crown"/><div><strong>国王游戏</strong><small>抽签出令 · 罚酒挑战</small></div><span>›</span></button><button type="button" class="pt-row" @click="u.go('divination')"><TerminalIcon name="crown"/><div><strong>每日占卜</strong><small>塔罗 · Rätselhaft 的今日解读</small></div><span>›</span></button><button type="button" class="pt-row" @click="openParty('eleven')"><TerminalIcon name="crown"/><div><strong>十点半</strong><small>轮流坐庄 · 输家罚酒</small></div><span>›</span></button><button type="button" class="pt-row" @click="openParty('truth')"><TerminalIcon name="crown"/><div><strong>真心话大冒险</strong><small>转酒瓶 · 双选题卡</small></div><span>›</span></button><button type="button" class="pt-row" @click="openParty('liar')"><TerminalIcon name="crown"/><div><strong>大话骰</strong><small>五骰叫号 · 斋与非 · 诈唬开骰</small></div><span>›</span></button><button v-for="g in lockedGames" :key="g" type="button" class="pt-row pt-game-locked" disabled><TerminalIcon name="crown"/><div><strong>{{g}}</strong><small>暂未开放</small></div></button><button type="button" class="pt-gold" @click="startRoom">创建房间 ›</button><h3 v-if="endedRoomsWithHistory.length">已结束的房间</h3><button v-for="r in endedRoomsWithHistory" :key="r.id" type="button" class="pt-row" @click="u.roomId=r.id;u.go('history')">{{r.name}} · 回看记录</button><h3 v-if="endedRoomsEmpty.length">未开始的已结束房间</h3><div v-for="r in endedRoomsEmpty" :key="'empty:'+r.id" class="pt-row"><TerminalIcon name="crown"/><div><strong>{{r.name}}</strong><small>未开始，未生成回看</small></div></div><h3>进行中的房间</h3><button v-for="r in u.t.rooms.filter(r=>!r.endedAt)" :key="r.id" type="button" class="pt-row" @click="u.openRoom(r.id)"><TerminalIcon name="crown"/><div><strong>{{r.name}}</strong><small>{{r.rounds.length}}轮记录 · {{r.members.length}}位受邀成员</small></div><span>›</span></button></template>
  <template v-else-if="u.page==='room'&&u.room"><div class="pt-game-hero"><TerminalIcon name="crown"/><h2>{{u.room.name}}</h2><p>{{u.room.style}} · 好友专属</p></div><article v-for="id in u.room.members" :key="id" class="pt-row"><TerminalActorAvatar :w="w" :id="id"/><strong>{{u.name(id)}}</strong><small>{{id==='player'?'房主 · 已就绪':{accepted:'已接受',declined:'未参加',pending:'等待回应'}[u.room.invitations[id]]}}</small><small v-if="id==='player'||u.room.invitations[id]==='accepted'" class="pt-tolerance">醉酒 <progress v-if="u.toleranceValue(id)!==undefined" :max="u.toleranceValue(id)" :value="u.room?.drunk?.[id]||0" :aria-label="u.name(id)+'醉酒度进度'"></progress><b>{{u.room?.drunk?.[id]||0}}/{{u.toleranceValue(id)??'?'}}</b></small><small v-else class="pt-muted">未参加</small><p v-if="id!=='player'&&u.room.inviteReplies?.[id]" class="pt-invite-reply">{{u.room.inviteReplies[id]}}</p><button v-if="id!=='player'&&u.room.invitations[id]!=='accepted'" type="button" :disabled="u.working" @click="u.beginInvite(id)">重新邀请</button></article><button type="button" :disabled="u.working||!!(u.round&&u.round.phase!=='complete')" @click="u.picked=[];u.go('invite-room')">邀请其他好友</button><p>已确认 {{1+Object.values(u.room.invitations).filter(s=>s==='accepted').length}} 人</p><button v-if="Object.values(u.room.invitations).some(s=>s!=='accepted')" type="button" :disabled="u.working" @click="u.beginInvite()">重新邀请未加入的好友</button><button v-if="u.round" type="button" class="pt-gold" @click="u.go('king')">{{u.round.phase==='complete'?'回到本轮互动':'继续当前轮'}}</button><p v-else-if="u.room.rounds.length" class="pt-muted">其他剧情分支的轮次仍保留在存档中，可在当前分支开始新一轮。</p><button v-if="!u.round||u.round.phase==='complete'" type="button" class="pt-gold" :disabled="u.working||Object.values(u.room.invitations).filter(s=>s==='accepted').length<2" @click="u.startRound">抽签开始{{u.room.rounds.length?'下一轮':'游戏'}}</button><button v-if="u.room.rounds.length" type="button" @click="u.go('history')">游戏记录</button><button type="button" @click="u.askEnd">结束游戏</button></template>
  <template v-else-if="u.page==='king'&&u.round">
   <p class="pt-round">第 {{String(u.round.number).padStart(2,'0')}} 轮</p><div class="pt-drunk-strip" v-if="drunkStripVisible" aria-label="醉酒与耐受度"><span v-for="id in roomParticipants" :key="id"><small>{{u.name(id)}}</small><progress v-if="u.toleranceValue(id)!==undefined" :max="u.toleranceValue(id)" :value="u.room?.drunk?.[id]||0" :aria-label="u.name(id)+'醉酒度进度'"></progress><b>{{u.room?.drunk?.[id]||0}}/{{u.toleranceValue(id)??'?'}}</b></span></div><div class="pt-king"><TerminalIcon name="crown"/><TerminalActorAvatar :w="w" :id="u.round.king"/><h2>本轮国王：{{u.name(u.round.king)}}</h2></div>
   <template v-if="u.round.phase==='command'"><div class="pt-hidden-cards"><span v-for="n in Object.keys(u.round.numbers).length" :key="n">？<small>秘密编号</small></span></div><small v-if="u.round.king!=='player'">你的编号：{{u.round.numbers.player}}</small><small v-else>你是国王，不持有编号。目标将在出令后揭晓。</small><template v-if="u.round.king==='player'"><label>输入你的命令<textarea v-model="u.draft" aria-label="国王命令" maxlength="1000" placeholder="写下本轮命令…" rows="4"/></label><p>选择目标编号</p><div class="pt-chips"><button v-for="n in Object.keys(u.round.numbers).length" :key="n" type="button" :class="{active:u.targets.includes(n)}" @click="u.targets=u.targets.includes(n)?u.targets.filter(i=>i!==n):[...u.targets,n]">{{n}}号</button></div><p>备选指令（选择后可编辑）</p><div class="pt-chips"><button v-for="text in ['分享一件今天开心的事。','夸奖一位参与者。','模仿一个有趣的表情。']" :key="text" type="button" @click="u.draft=text">{{text}}</button></div></template><button type="button" class="pt-gold" :disabled="u.working" @click="u.command">{{u.round.king==='player'?'发布命令':'请国王出令'}}</button></template>
   <template v-else><div class="pt-reveal"><article v-for="id in targetActors(u.round)" :key="id"><b>{{u.round.numbers[id]}}号</b><TerminalActorAvatar :w="w" :id="id"/><strong>{{u.name(id)}}</strong></article></div><GameChat :lines="roundDialogueLines(u.round)" :name="u.name" label="国王游戏连续对话"/><section v-for="fact in kingPenaltyFacts(u.round)" :key="'fact:'+fact.id+':'+fact.text" class="pt-penalty"><strong>{{u.name(fact.id)}}接受游戏惩罚</strong><p>{{fact.text}}</p></section><button v-if="npcWaiting" type="button" class="pt-gold" :disabled="u.working" @click="u.retryReact">获取角色回应</button><form @submit.prevent="u.gameInteract"><h3>游戏互动</h3><AutoTextarea v-model="u.draft" aria-label="游戏互动" placeholder="写下你的台词或动作；普通发言不会推进轮次。" maxlength="2000"/><div class="pt-actions"><button type="submit" class="pt-primary" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')">发送互动</button><button v-if="mineWaiting" type="button" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')" @click="u.playerReply(false)">完成命令并回应</button><button v-if="mineWaiting" type="button" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')" @click="u.playerReply(true)">拒绝并接受惩罚</button></div></form><template v-if="u.round.phase==='complete'"><div class="pt-complete">✓ 本轮结束</div><button type="button" class="pt-gold" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')" @click="u.startRound">下一轮</button></template></template><button type="button" class="pt-link" @click="u.go('history')">查看游戏记录</button><button type="button" @click="u.go('games')">暂时离开</button><button type="button" @click="u.askEnd">结束游戏</button>
  </template>
  <template v-else-if="u.page==='history'&&u.room"><h2>{{u.room.name}}</h2><p v-if="u.room.endedAt">游戏已结束{{u.room.endReason==='round-limit'?' · 本局15轮已结算':''}}</p><div class="pt-drunk-strip" v-if="drunkStripVisible" aria-label="醉酒与耐受度"><span v-for="id in roomParticipants" :key="id"><small>{{u.name(id)}}</small><progress v-if="u.toleranceValue(id)!==undefined" :max="u.toleranceValue(id)" :value="u.room?.drunk?.[id]||0" :aria-label="u.name(id)+'醉酒度进度'"></progress><b>{{u.room?.drunk?.[id]||0}}/{{u.toleranceValue(id)??'?'}}</b></span></div><article v-if="u.room.afterparty" class="pt-card pt-afterparty"><h3>散场复盘</h3><template v-if="u.room.afterparty.scenes"><section v-for="scene in u.room.afterparty.scenes" :key="scene.actorId"><h4>{{u.name(scene.actorId)}} · 醉后独处</h4><template v-if="scene.status==='ready'"><p>{{scene.text}}</p><small>{{scene.summary}}</small></template><template v-else><p role="status">{{scene.error||'本篇待生成'}}</p><p v-if="scene.draft">{{scene.draft}}</p><button type="button" :disabled="u.working" @click="u.retryAfterparty(u.room!.id,scene.actorId)">只重试本篇</button></template></section></template><template v-else-if="u.room.afterparty.status==='ready'"><p>{{u.room.afterparty.text}}</p><small v-if="u.room.afterparty.summary">摘要：{{u.room.afterparty.summary}}</small></template><template v-else-if="u.room.afterparty.status==='failed'"><p role="alert">复盘生成失败：{{u.room.afterparty.error||'未知错误'}}</p><button type="button" :disabled="u.working" @click="u.retryAfterparty(u.room!.id)">重试生成复盘</button></template><template v-else><p role="status">复盘待生成，可稍后重试。</p><button type="button" :disabled="u.working" @click="u.retryAfterparty(u.room.id)">补写复盘</button></template></article><p v-if="!u.gameHistory.length" class="pt-empty">未开始，未生成回看</p><details v-for="r in [...u.gameHistory].reverse()" :key="r.number" class="pt-card"><summary>第{{r.number}}轮 · {{u.name(r.king)}} · {{r.phase==='complete'?'本轮已完成':u.room.endedAt?'未完成（游戏已结束）':'进行中'}}</summary><GameChat :lines="[{id:r.king,text:r.command||'尚未出令'},...roundDialogueLines(r)]" :name="u.name" :label="'第'+r.number+'轮国王游戏对话'"/><section v-for="fact in kingPenaltyFacts(r)" :key="fact.id+':'+fact.text" class="pt-penalty"><strong>{{u.name(fact.id)}}接受游戏惩罚</strong><p>{{fact.text}}</p></section><small v-if="(r.interactions||[]).some(i=>i.status!=='ready')">部分互动未完成{{u.room.endedAt?'（游戏已结束，互动已停止）':'，可返回本轮重试'}}</small></details></template>

   <template v-else-if="u.page==='divination'">
   <div class="pt-div-hero"><img class="pt-div-cat" :src="divinationCatImage" alt="占卜师黑猫 Rätselhaft"><div><h2>每日占卜</h2><p>Rätselhaft 已铺好塔罗桌</p><DivinationCountdown :deadline="u.divinationRefreshAt" :active="props.active" @expire="u.refreshDay"/></div></div>
   <div class="pt-tabs"><button type="button" :class="{active:divTab==='mine'}" @click="divTab='mine'">我的今日占卜</button><button type="button" :class="{active:divTab==='peek'}" @click="divTab='peek'">偷看角色运势</button></div>
   <template v-if="divTab==='mine'">
    <template v-if="u.myDivination">
     <div class="pt-div-cards"><article v-for="(c,i) in u.myDivination.cards" :key="c.id" class="pt-tarot" :class="{reversed:c.reversed}"><b>{{suitGlyph(c.suit)}}</b><strong>{{c.name}}</strong><small>{{suitName(c.suit)}}</small><em>{{reversedLabel(c.reversed)}}</em><span>{{divinationPositions[i]}}</span></article></div>
     <template v-if="u.myDivination.reading.status==='ready'">
      <article v-for="[title,text] in readingBlocks(u.myDivination)" :key="title" class="pt-card pt-div-reading"><h3>{{title}}</h3><p>{{text}}</p></article>
     </template>
     <article v-else-if="u.myDivination.reading.status==='failed'" class="pt-card pt-div-reading"><p role="alert">解读生成失败：{{u.myDivination.reading.error||'未知错误'}}</p><p v-if="u.myDivination.reading.draft" class="pt-muted">已保留草稿：{{u.myDivination.reading.draft}}</p><button type="button" class="pt-gold" :disabled="u.working" @click="u.retryDivination('player')">重试解读（牌面不变）</button></article>
     <article v-else class="pt-card pt-div-reading"><p role="status">牌已锁定，解读待生成。</p><button type="button" class="pt-gold" :disabled="u.working" @click="u.retryDivination('player')">补写解读（牌面不变）</button></article>
    </template>
    <template v-else>
     <p class="pt-empty">今天的牌还没有抽。</p><button type="button" class="pt-gold" :disabled="u.working" @click="u.drawDaily">抽取今日塔罗</button><small>每天一份，抽过今日就固定了。</small>
    </template>
   </template>
   <template v-else>
    <p class="pt-muted">偷看一位角色的今日运势，只有你知道；他们不会发现自己被偷看，也不会占用你自己的抽牌。</p>
    <p v-if="!u.peekCandidates.length" class="pt-empty">本档还没有已知角色可偷看。</p>
    <button v-for="a in u.peekCandidates" :key="a.id" type="button" class="pt-row" @click="u.peekDaily(a.id)"><span class="pt-avatar"><CharacterAvatar :w="w" :id="a.id"/></span><div><strong>{{u.name(a.id)}}</strong><small>{{a.identity||'本档角色'}}</small></div><span>›</span></button>
    <template v-if="u.peekRecord">
     <h3>{{u.name(u.peekActorId)}} 的今日占卜</h3>
     <div class="pt-div-cards"><article v-for="(c,i) in u.peekRecord.cards" :key="c.id" class="pt-tarot" :class="{reversed:c.reversed}"><b>{{suitGlyph(c.suit)}}</b><strong>{{c.name}}</strong><small>{{suitName(c.suit)}}</small><em>{{reversedLabel(c.reversed)}}</em><span>{{divinationPositions[i]}}</span></article></div>
     <template v-if="u.peekRecord.reading.status==='ready'">
      <article v-for="[title,text] in readingBlocks(u.peekRecord)" :key="title" class="pt-card pt-div-reading"><h3>{{title}}</h3><p>{{text}}</p></article>
      <article v-if="u.peekRecord.reading.reaction" class="pt-card pt-div-reaction"><h3>{{u.name(u.peekActorId)}} 看到自己的运势…</h3><p>{{u.peekRecord.reading.reaction}}</p></article>
     </template>
     <article v-else-if="u.peekRecord.reading.status==='failed'" class="pt-card pt-div-reading"><p role="alert">解读生成失败：{{u.peekRecord.reading.error||'未知错误'}}</p><button type="button" class="pt-gold" :disabled="u.working" @click="u.retryDivination(u.peekActorId)">重试解读（牌面不变）</button></article>
     <article v-else class="pt-card pt-div-reading"><p role="status">牌已锁定，解读待生成。</p><button type="button" class="pt-gold" :disabled="u.working" @click="u.retryDivination(u.peekActorId)">补写解读（牌面不变）</button></article>
    </template>
   </template>
   <template v-if="u.visibleDivinationHistory.length">
    <h3>历史占卜（只读）</h3>
    <details v-for="d in u.visibleDivinationHistory" :key="d.day+'|'+d.actorId" class="pt-card"><summary>{{d.actorId==='player'?'我':u.name(d.actorId)}} · {{d.cards.map(c=>c.name+(c.reversed?'（逆位）':'')).join('、')}}</summary>
     <template v-if="d.reading.status==='ready'"><p v-for="[title,text] in readingBlocks(d)" :key="title"><b>{{title}}：</b>{{text}}</p><p v-if="d.reading.reaction&&d.actorId!=='player'"><b>TA 的反应：</b>{{d.reading.reaction}}</p></template>
     <template v-else><p v-if="d.reading.status==='failed'">解读未完成：{{d.reading.error||'生成失败'}}</p><p v-else>解读待生成。</p><p v-if="d.reading.draft" class="pt-muted">已保留草稿：{{d.reading.draft}}</p><button type="button" class="pt-gold" :disabled="u.working" @click="u.backfillDivination(d.day,d.actorId)">补写当天的解读（牌面不变）</button></template>
    </details>
    <button v-if="u.visibleDivinationHistory.length<u.divinationHistory.length" type="button" @click="u.divinationHistoryPage++">显示更早的记录</button>
   </template>
  </template>
  <template v-else-if="u.page==='account'"><div class="pt-profile pt-my-profile"><span class="pt-avatar profile-avatar"><img v-if="u.t.avatar" :src="avatarDisplay" :style="u.avatarStyle" alt="我的头像"><TerminalIcon v-else name="user"/></span><h2>{{w.active?.persona.name||'我的终端'}}</h2><small>终端码：{{u.ownCode||'剧情尚未提供'}}</small><p>{{u.t.bio||'这个家伙很懒，还没有写个人简介喵~'}}</p></div><input ref="avatarInput" class="pt-avatar-file" type="file" accept="image/*" :disabled="u.working||w.busy" aria-label="导入头像文件" @change="avatarChange"><button type="button" :disabled="u.working||w.busy" @click="avatarInput?.click()">{{u.working?'处理中…':'导入文件'}}</button><template v-if="u.t.avatar"><p class="pt-muted">此处调整用于个人资料、聊天及群成员头像；拖动实时预览，松开后保存。</p><label>头像缩放<input type="range" min="1" max="2.5" step="0.05" :value="u.avatarDraft.scale" @input="u.adjustAvatar('scale',Number(($event.target as HTMLInputElement).value))" @change="u.flushAvatar"></label><label>水平位置<input type="range" min="-30" max="30" :value="u.avatarDraft.x" @input="u.adjustAvatar('x',Number(($event.target as HTMLInputElement).value))" @change="u.flushAvatar"></label><label>垂直位置<input type="range" min="-30" max="30" :value="u.avatarDraft.y" @input="u.adjustAvatar('y',Number(($event.target as HTMLInputElement).value))" @change="u.flushAvatar"></label></template><label>一句话简介<input v-model="u.bioDraft" aria-label="个人简介" maxlength="160" placeholder="这个家伙很懒，还没有写个人简介喵~"></label><button type="button" class="pt-primary" :disabled="u.working" @click="u.saveBio">保存资料</button><button v-if="u.t.avatar" type="button" :disabled="u.working" @click="u.run(()=>u.commit(t=>{t.avatar='';t.avatarView=undefined}))">恢复默认头像</button><p class="pt-muted">终端 API：{{u.terminalProfile?.name||'未配置'}}</p><div class="pt-order" role="group" aria-label="通讯顺序"><small>通讯顺序</small><button type="button" :class="{active:w.terminalOrder==='story-first'}" :disabled="w.busy||w.terminalBusy" @click="w.setTerminalOrder('story-first')">正文 → 终端</button><button type="button" :class="{active:w.terminalOrder==='terminal-first'}" :disabled="w.busy||w.terminalBusy" @click="w.setTerminalOrder('terminal-first')">终端 → 正文</button></div><p class="pt-muted">手机：{{w.terminalEnabled?'已开启':'已关闭'}} · 顺序只影响下一轮起的新通讯，已有记录不变。</p><button type="button" @click="w.panel='settings';$emit('close')">终端 API 设置 ›</button><button type="button" :disabled="u.working" @click="u.retryAutomatic">自动通讯同步说明</button></template>

  <PartyGameRoom v-if="partyVisited" v-show="u.page==='party'" ref="partyView" :w="w" :active="props.active&&u.page==='party'" :kind="partyKind" @back="u.go('games')" />
 </main>
 <div v-if="u.endConfirm" class="pt-end-confirm" role="dialog" aria-modal="true" aria-label="结束游戏"><div class="pt-card"><p>结束这场游戏？已有记录会保留；未完成的轮次将停止，结束后不能继续本房间。</p><p v-if="u.endSaveFailed">结束状态未保存，请重试保存。</p><button type="button" :disabled="u.ending" @click="u.endConfirm=''">取消</button><button type="button" :disabled="u.ending" @click="u.endGame">{{u.ending?'正在保存…':u.endSaveFailed?'重试保存':u.working?'停止请求并结束':'确认结束'}}</button></div></div>
 <nav class="pt-dock" aria-label="终端导航"><button v-for="item in [{id:'home',icon:'home',name:'桌面'},{id:'messages',icon:'chat',name:'通讯'},{id:'friends',icon:'friends',name:'好友'},{id:'account',icon:'user',name:'我的'}]" :key="item.id" type="button" :class="{active:nav===item.id}" :aria-current="nav===item.id?'page':undefined" @click="u.go(item.id)"><TerminalIcon :name="item.icon"/><span>{{item.name}}<em v-if="item.id==='friends'&&u.incoming.length"> {{u.incoming.length}}</em></span></button></nav><div class="pt-home-indicator" aria-hidden="true"></div>
</section>
